قرر
القانون الآتي نصه:$m226$,'8a800eb7da03c55c991e98be7350c9da',DATE '2015-02-17',NULL,'active',NULL,NULL,NULL),
(1,0,1,$m226$يقصد - في تطبيق أحكام هذا القانون - بالألفاظ والعبارات التالية المعاني المبينة قرين كل منها:
الكيان الإرهابي: الجمعيات أو المنظمات أو الجماعات أو العصابات أو الخلايا أو غيرها من التجمعات، أيًا كان شكلها القانوني أو الواقعي، متى مارست أو كان الغرض منها الدعوة بأية وسيلة في داخل أو خارج البلاد إلى إيذاء الأفراد أو إلقاء الرعب بينهم أو تعريض حياتهم أو حرياتهم أو حقوقهم أو أمنهم للخطر أو إلحاق الضرر بالبيئة أو بالمواد الطبيعية أو بالآثار أو بالاتصالات أو المواصلات البرية أو الجوية أو البحرية أو بالأموال أو بالمباني أو بالأملاك العامة أو الخاصة أو احتلالها أو الاستيلاء عليها أو منع أو عرقلة السلطات العامة أو الجهات أو الهيئات القضائية أو مصالح الحكومة أو الوحدات المحلية أو دور العبادة أو المستشفيات أو مؤسسات ومعاهد العلم، أو غيرها من المرافق العامة، أو البعثات الدبلوماسية والقنصلية، أو المنظمات والهيئات الإقليمية والدولية في مصر من القيام بعملها أو ممارستها لكل أو بعض أوجه نشاطها، أو مقاومتها، أو تعطيل المواصلات العامة أو الخاصة أو منع أو عرقلة سيرها أو تعريضها للخطر بأية وسيلة كانت، أو كان الغرض منها الدعوة بأية وسيلة إلى الإخلال بالنظام العام أو تعريض سلامة المجتمع أو مصالحه أو أمنه للخطر أو تعطيل أحكام الدستور أو القوانين أو منع إحدى مؤسسات الدولة أو إحدى السلطات العامة من ممارسة أعمالها، أو الاعتداء على الحرية الشخصية للمواطن أو غيرها من الحريات والحقوق العامة التي كفلها الدستور والقانون، أو الإضرار بالوحدة الوطنية أو السلام الاجتماعي أو الأمن القومي.
ويسرى ذلك على الجهات والأشخاص المذكورين متى مارسوا أو استهدفوا أو كان غرضهم تنفيذ أي من تلك الأعمال ولو كانت غير موجهة إلى جمهورية مصر العربية.
الإرهابي: كل شخص طبيعي يرتكب أو يشرع في ارتكاب أو يحرض أو يهدد أو يخطط في الداخل أو الخارج لجريمة إرهابية بأية وسيلة كانت، ولو بشكل منفرد، أو يساهم في هذه الجريمة في إطار مشروع إجرامي مشترك، أو تولى قيادة أو زعامة أو إدارة أو إنشاء أو تأسيس أو اشتراك في عضوية أي من الكيانات الإرهابية المنصوص عليها في المادة رقم (1) من هذا القانون أو قام بتمويلها، أو ساهم في نشاطها مع علمه بذلك.
الأموال: جميع الأصول والممتلكات أيًا كان نوعها، سواء كانت مادية أو معنوية، منقولة أو ثابتة، بما في ذلك المستندات والعملات الوطنية أو الأجنبية، والأوراق المالية أو التجارية، والصكوك والمحررات المثبتة لكل ما تقدم أيًا كان شكلها، وجميع الحقوق المتعلقة بأي منها.
التمويل: جمع أو تلقى أو حيازة أو إمداد أو نقل أو توفير أموال أو أسلحة أو ذخائر أو مفرقعات أو مهمات أو آلات أو بيانات أو معلومات أو مواد أو غيرها، بشكل مباشر أو غير مباشر، وبأية وسيلة كانت، وذلك بقصد استخدامها، كلها أو بعضها في ارتكاب أية جريمة إرهابية أو العلم بأنها ستستخدم في ذلك، أو بتوفير ملاذ آمن لإرهابي أو أكثر، أو لمن يقوم بتمويله بأي من الطرق المتقدم ذكرها.
تجميد الأموال: الحظر المؤقت الذى يفرضه على نقل الأموال أو تحريكها أو تبديلها أو تحويلها أو التصرف فيها، وذلك بناءً على القرار الصادر وفقًا لنص المادة (3) من هذا القانون.$m226$,'12f2e518b8ca7134e38cee3f5537bf62',DATE '2015-02-17',DATE '2020-03-03','amended',14,2020,$m226$النص قبل تعديل القانون رقم 14 لسنة 2020 كما أورده المصدر فى الحاشية («نص المادة قبل التعديل»).$m226$),
(1,0,2,$m226$يقصد - في تطبيق أحكام هذا القانون - بالألفاظ والعبارات التالية المعاني المبينة قرين كل منها:
الكيان الإرهابي: الجمعيات أو المنظمات أو الجماعات أو العصابات أو الخلايا أو الشركات أو الاتحادات وما في حكمها أو غيرها من التجمعات أياً كانت طبيعتها أو شكلها القانوني أو الواقعي، متى مارست أو كان الغرض منها الدعوة بأي وسيلة في داخل البلاد أو خارجها إلى إيذاء الأفراد أو إلقاء الرعب بينهم أو تعريض حياتهم أو حرياتهم أو حقوقهم أو أمنهم للخطر أو إلحاق الضرر بالبيئة أو بالموارد الطبيعية أو بالآثار أو بالاتصالات أو المواصلات البرية أو الجوية أو البحرية أو بالأموال أو الأصول الأخرى أو بالمباني أو بالأملاك العامة أو الخاصة أو احتلالها أو الاستيلاء عليها أو منع أو عرقلة السلطات العامة أو الجهات أو الهيئات القضائية أو مصالح الحكومة أو الوحدات المحلية أو دور العبادة أو المستشفيات أو مؤسسات ومعاهد العلم أو غيرها من المرافق العامة أو البعثات الدبلوماسية والقنصلية أو المنظمات والهيئات الإقليمية والدولية في مصر من القيام بعملها أو ممارستها لكل أوجه نشاطها أو بعضه، أو مقاومتها أو تعطيل المواصلات العامة أو الخاصة أو منع سيرها أو عرقلته أو تعريضها للحظر بأي وسيلة كانت أو كان الغرض منها الدعوة بأي وسلة إلى الإخلال بالنظام العام أو تعريض سلامة المجتمع أو مصالحه أو أمنه للخطر أو تعطيل أحكام الدستور أو القوانين أو منع إحدى مؤسسات الدولة أو إحدى السلطات العامة من ممارسة أعمالها أو الاعتداء على الحرية الشخصية للمواطن أو غيرها من الحريات والحقوق العامة التي كفلها الدستور والقانون أو الإضرار بالوحدة الوطنية أو السلام الاجتماعي أو الأمن القومي.
ويسرى ذلك على الجهات والأشخاص المذكورين متى مارسوا أو استهدفوا أو كان غرضهم تنفيذ أي من تلك الأعمال ولو كانت غير موجهة إلى جمهورية مصر العربية.
الإرهابي: كل شخص طبيعي يرتكب أو يشرع في ارتكاب أو يحرض أو يهدد أو يخطط في الداخل أو الخارج لجريمة إرهابية بأية وسيلة كانت، ولو بشكل منفرد، أو يساهم في هذه الجريمة في إطار مشروع إجرامي مشترك، أو تولى قيادة أو زعامة أو إدارة أو إنشاء أو تأسيس أو اشتراك في عضوية أي من الكيانات الإرهابية المنصوص عليها في المادة رقم (1) من هذا القانون أو قام بتمويلها، أو ساهم في نشاطها مع علمه بذلك.
الأموال أو الأصول الأخرى: جميع الأصول المالية والموارد الاقتصادية ومنها النفط والموارد الطبيعية الأخرى والممتلكات أيا كان نوعها سواء كانت مادية أو معنوية، منقولة أو ثابتة، أيا كانت وسيلة الحصول عليها، والوثائق والأدوات القانونية والعملات الوطنية أو الأجنبية، والأوراق المالية أو التجارية، والصكوك والمحررات المثبتة لكل ما تقدم أياً كان شكلها، بما في ذلك الشكل الرقمي أو الإلكتروني وجميع الحقوق المتعلقة بأي منها بما في ذلك الائتمان المصرفي والشيكات السياحية والشيكات المصرفية والاعتمادات المستندية، وأي فوائد أو أرباح أو مصادر دخل أخرى مترتبة على هذه الأموال أو الأصول أو متولدة منها، أو أي أصول أخرى استخدمت أو يحتمل استخدامها للحصول على تمويل أو منتجات أو خدمات.
التمويل: جمع أو تلقى أو حيازة أو إمداد أو نقل أو توفير أموال أو أسلحة أو ذخائر أو مفرقعات أو مهمات أو آلات أو بيانات أو معلومات أو مواد أو غيرها، بشكل مباشر أو غير مباشر، وبأية وسيلة كانت، وذلك بقصد استخدامها، كلها أو بعضها في ارتكاب أية جريمة إرهابية أو العلم بأنها ستستخدم في ذلك، أو بتوفير ملاذ آمن لإرهابي أو أكثر، أو لمن يقوم بتمويله بأي من الطرق المتقدم ذكرها.
تجميد الأموال أو الأصول الأخرى: الحظر المؤقت الذى يفرضه على نقل الأموال أو الأصول الأخرى أو تحريكها أو تبديلها أو تحويلها أو التصرف فيها، وذلك بناءً على القرار الصادر وفقًا لنص المادة (3) من هذا القانون.
*تستبدل عبارة الأموال أو الأصول الأخرى بكلمة الأموال بموجب قانون رقم 14 لسنة 2020.
*يستبدل بتعريفي (الكيان الإرهابي) و(الأموال) الواردين بالمادة (1) بموجب قانون رقم 14 لسنة 2020.$m226$,'62cd4caf075bc6626d4603513d2331da',DATE '2020-03-04',NULL,'active',14,2020,$m226$عدلت تعريفات «الكيان الإرهابي» و«الأموال» و«تجميد الأموال» بالقانون رقم 14 لسنة 2020 (إضافة الشركات والاتحادات وما فى حكمها والأصول الأخرى وتفصيل تعريف الأموال). تاريخ النفاذ مسجل تقريباً (يوم النشر التالى، 4 مارس 2020).$m226$),
(2,0,1,$m226$تُعد النيابة العامة قائمةً تسمى (قائمة الكيانات الإرهابية)، تدرج عليها الكيانات الإرهابية التي تُقرر الدائرة المختصة المنصوص عليها في المادة رقم (3) من هذا القانون إدراجها على القائمة، وتلك التي تصدر في شأنها أحكام جنائية نهائية بإسباغ هذا الوصف عليها.
كما تُعد النيابة العامة قائمةً أخرى تسمى (قائمة الإرهابيين)، تدرج عليها أسماء الإرهابيين، إذا قررت الدائرة المشار إليها إدراجهم عليها، وكذلك إذا صدر في شأن أي منهم حكم جنائي بإسباغ هذا الوصف عليه.
وتسرى على هذه القائمة ذات الأحكام المقررة في شأن قائمة الكيانات الإرهابية.$m226$,'dad2f57dfd42b1daacfa42e443b2abb3',DATE '2015-02-17',NULL,'active',NULL,NULL,NULL),
(3,0,1,$m226$تختص دائرة أو أكثر من دوائر الجنايات بمحكمة استئناف القاهرة تحددها الجمعية العمومية للمحكمة سنويًا تكون منعقدة فى غرفة المشورة، بنظر طلبات الإدراج على قائمتي الكيانات الإرهابية والإرهابيين.
ويقدم طلب الادراج من النائب العام الى الدائرة المختصة مشفوعا بالتحقيقات أو المستندات او التحريات او المعلومات المؤيدة لهذا الطلب.
ويكون طلب الإدراج بالنسبة للكيانات والأشخاص غير الموجهة أعمالهم لجمهورية مصر العربية بناءً على طلب يقدم إلى النائب العام من وزارة الخارجية بالتنسيق مع وزارة العدل، أو من جهات الدولة الأمنية إلى النائب العام.
وتفصل الدائرة المختصة في طلب الإدراج بقرار مسبب خلال سبعة أيام من تاريخ تقديم الطلب لها مستوفيًا المستندات اللازمة.
*الفقرة الثانية معدلة بموجب قانون رقم 11 لسنة 2017.$m226$,'c952b70b5506f2dbccba1eb678d0f6c7',DATE '2017-04-23',NULL,'active',11,2017,$m226$الفقرة الثانية معدلة بالقانون رقم 11 لسنة 2017. نصها قبل التعديل كما ورد فى المصدر: «ويقدم طلب الإدراج من النائب العام إلى الدائرة المختصة مشفوعًا بالتحقيقات والمستندات المؤيدة لهذا الطلب». تاريخ نفاذ التعديل مسجل تقريباً.$m226$),
(4,0,1,$m226$يكون الادراج على أي من القائمتين لمدة لا تجاوز خمس سنوات.
فإذا انقضت مدة الإدراج دون صدور حكم نهائي بإسباغ الوصف الجنائي المنصوص عليه في المادة رقم (1) من هذا القانون على الكيان المدرج أو الإرهابي، تعين على النيابة العامة إعادة العرض على الدائرة المشار إليها للنظر في مد الإدراج لمدة أخرى، وإلا وجب رفع اسم الكيان أو الشخص الطبيعي من القائمة من تاريخ انقضاء تلك المدة.
وللنائب العام خلال مدة الإدراج، في ضوء ما يبديه من مبررات، أن يطلب من الدائرة المنصوص عليها في المادة (3) من هذا القانون رفع اسم الكيان أو الشخص الطبيعي المدرج على أي من القائمتين.
*الفقرة الأولى معدلة بموجب قانون رقم 11 لسنة 2017.$m226$,'e93362a7c1ca2b47d809c67b132c7dd1',DATE '2017-04-23',NULL,'active',11,2017,$m226$الفقرة الأولى معدلة بالقانون رقم 11 لسنة 2017. نصها قبل التعديل كما ورد فى المصدر: «يكون الإدراج على أي من القائمتين لمدة لا تجاوز ثلاث سنوات.». تاريخ نفاذ التعديل مسجل تقريباً.$m226$),
(5,0,1,$m226$ينشر قرار الإدراج على أي من القائمتين، وقرار مد مدته وقرار رفع الاسم من أي منهما في الوقائع المصرية.$m226$,'8a984784a7d5b148276646c32f283170',DATE '2015-02-17',DATE '2020-01-14','amended',2,2020,$m226$النص قبل تعديل القانون رقم 2 لسنة 2020 كما أورده المصدر فى الحاشية.$m226$),
(5,0,2,$m226$يُنشر قرار الإدراج على أي من القائمتين، وقرار مد مدته وقرار رفع الاسم من أي منهما في الوقائع المصرية، دون مقابل.
*معدلة بموجب قانون رقم 2 لسنة 2020.$m226$,'df6d98459e4f02c1afd50eaf59e81f5f',DATE '2020-01-15',NULL,'active',2,2020,$m226$أضيفت عبارة «دون مقابل» بالقانون رقم 2 لسنة 2020. تاريخ النفاذ مسجل تقريباً.$m226$),
(6,0,1,$m226$لذوي الشأن وللنيابة العامة الطعن في القرار الصادر في شأن الإدراج على أي من القائمتين المشار إليهما خلال ستين يومًا من تاريخ نشر القرار أمام الدائرة الجنائية بمحكمة النقض التي تحددها الجمعية العمومية للمحكمة سنويًا، وذلك وفقًا للإجراءات المعتادة للطعن.
ويكون لذوي الشأن تضمين الطعن طلب السماح باستثناء بعض المبالغ من الأموال أو الأصول الأخرى المجمدة للوفاء بمتطلباتهم من نفقات يستلزمها شراء المواد الغذائية أو الإيجار أو الأدوية والعلاج الطبي أو غيرها من النفقات.
*الفقرة الثانية مضافة بموجب قانون رقم 14 لسنة 2020.$m226$,'357dc4a55f84a75b47497ba61a87fd8c',DATE '2020-03-04',NULL,'active',14,2020,$m226$الفقرة الثانية مضافة بالقانون رقم 14 لسنة 2020 (طلب استثناء مبالغ للنفقات من الأموال المجمدة). تاريخ النفاذ مسجل تقريباً. النص الأصلى للفقرة الأولى قبل التعديل غير وارد منفصلاً فى المصدر.$m226$),
(7,0,1,$m226$تترتب بقوة القانون على نشر قرار الإدراج، وطوال مدته، الآثار التالية ما لم تقرر الدائرة المنصوص عليها في المادة (3) من هذا القانون خلاف ذلك:
أولاً - بالنسبة للكيانات الإرهابية:
1 - حظر الكيان الإرهابي، ووقف أنشطت
2 - غلق الأمكنة المخصصة له، وحظر اجتماعاته
3 - حظر تمويل أو جمع الأموال أو الأشياء للكيان سواء بشكل مباشر أو غير مباشر
4 - تجميد الأموال المملوكة للكيان، أو لأعضائه متى كانت مستخدمة في ممارسة النشاط الإرهابي
5 - حظر الانضمام للكيان أو الدعوة إلى ذلك، أو الترويج له، أو رفع شعاراته
ثانياً - بالنسبة للإرهابيين:
1 - الإدراج على قوائم المنع من السفر وترقب الوصول، أو منع الأجنبي من دخول البلاد
2 - سحب جواز السفر أو إلغاؤه، أو منع إصدار جواز سفر جديد
3 - فقدان شرط حسن السمعة والسيرة اللازم لتولى الوظائف والمناصب العامة أو النيابية
4 - تجميد أموال الإرهابي متى استخدمت في ممارسة نشاطه الإرهابي
5 - حظر ممارسة كافة الانشطة الأهلية او الدعوية تحت أي مسمى.
وتلتزم جميع سلطات وجهات وهيئات وأجهزة الدولة، كل في حدود اختصاصه، بإعمال وإنفاذ الآثار المشار إليها، وبإبلاغ الجهات المعنية في الداخل والخارج لإعمال آثار الإدراج على أي من القائمتين.
*البند (5) من ثانياً مضاف بموجب قانون رقم 11 لسنة 2017.$m226$,'f664e26b811947803e88057b275b5b4b',DATE '2017-04-23',DATE '2020-03-03','amended',14,2020,$m226$النص قبل تعديل القانون رقم 14 لسنة 2020 (بعد إضافة البند 5 من «ثانياً» بالقانون رقم 11 لسنة 2017) كما أورده المصدر فى الحاشية؛ ورد البند 5 فى المصدر بعد الفقرة الأخيرة بسبب تنسيق الحاشية فنُقل هنا إلى موضعه المنطقى بعد البند 4 دون تغيير فى لفظه. تاريخ نفاذ تعديل 2017 مسجل تقريباً.$m226$),
(7,0,2,$m226$تترتب بقوة القانون على نشر قرار الإدراج، وطوال مدته، الآثار التالية ما لم تقرر الدائرة المنصوص عليها في المادة (3) من هذا القانون خلاف ذلك.
أولاً - بالنسبة للكيانات الإرهابية:
1 - حظر الكيان الإرهابي، ووقف أنشطته.
2 - غلق الأمكنة المخصصة له، وحظر اجتماعاته.
3 - حظر تمويل أو جمع الأموال أو الأشياء للكيان سواء بشكل مباشر أو غير مباشر.
4 - تجميد الأموال أو الأصول الأخرى المملوكة للكيان أو لأعضائه سواء كان يملكها الكيان بالكامل أو في صورة حصة في ملكية مشتركة، والعائدات المتولدة منها، أو التي يتحكم فيها الكيان بشكل مباشر أو غير مباشر، والأموال أو الأصول الأخرى الخاصة بالأشخاص والكيانات التي تعمل من خلاله.
5 - حظر الانضمام إلى الكيان أو الدعوة إلى ذلك، أو الترويج له، أو رفع شعاراته.
ثانياً - بالنسبة للإرهابيين:
1 - الإدراج على قوائم المنع من السفر وترقب الوصول، أو منع الأجنبي من دخول.
2 - سحب جواز السفر أو إلغاؤه أو منع إصدار جواز سفر جديد أو تجديده.
3 - فقدان شرط حسن السمعة والسيرة اللازم لتولى الوظائف والمناصب العامة أو النيابية أو المحلية.
4 - عدم التعيين أو التعاقد بالوظائف العامة أو بشركات القطاع العام أو قطاع الأعمال العام، بحسب الأحوال.
5 - الوقف عن العمل مع صرف نصف الأجر.
6 - تجميد الأموال أو الأصول الأخرى المملوكة للإرهابي، سواء بالكامل أو في صورة حصة في ملكية مشتركة، والعائدات المتولدة منها، أو التي يتحكم فيها بشكل مباشر أو غير مباشر، والأموال أو الأصول الأخرى الخاصة بالأشخاص والكيانات التي تعمل من خلاله.
7 - حظر ممارسة جميع الأنشطة الاهلية أو الدعوية تحت أي مسمى.
8 - حظر تمويل أو جمع الأموال أو الأشياء للإرهابي سواء بشكل مباشر أو غير مباشر وحظر تلقى الأموال أو تحويلها وكذا غيرها من الخدمات المالية المشابهة.
9 - وقف العضوية في النقابات المهنية ومجالس إدارات الشركات والجمعيات والمؤسسات وأي كيان تساهم فيه الدولة أو المواطنون بنصيب ما ومجالس إدارات الأندية والاتحادات الرياضية وأي كيان مخصص للمنفعة العامة.
وفى جميع الأحوال، تراعى حقوق غير الحسن النية عند تنفيذ الآثار المترتبة على نشر قرارات الإدراج الصادرة وفقًا لأحكام هذه المادة.
وتلتزم جميع سلطات وجهات وهيئات وأجهزة الدولة، كل في حدود اختصاصه، بإعمال وإنفاذ الآثار المشار إليها، وبإبلاغ الجهات المعنية في الداخل والخارج لإعمال آثار الإدراج على أي من القائمتين.
*معدلة بموجب قانون رقم 14 لسنة 2020.$m226$,'f24e18d363619f15aa956bf7c5e858d2',DATE '2020-03-04',NULL,'active',14,2020,$m226$عدلت المادة بالقانون رقم 14 لسنة 2020 (توسيع آثار الإدراج وتجميد الأموال أو الأصول الأخرى وإضافة بنود المنع والإيقاف والحظر). تاريخ النفاذ مسجل تقريباً.$m226$),
(8,0,1,$m226$في الأحوال التي تقتضي فيها طبيعة الأموال أو الأصول الأخرى المجمدة تعيين من يديرها، يجب أن يحدد قرار المحكمة من يدير هذا الأموال أو الأصول الأخرى بعد أخذ رأى النيابة العامة.
وعلى من يعين للإدارة أن يتسلم الأموال أو الأصول الأخرى المجمدة ويبادر إلى جردها بحضور ذوي الشأن وممثل للنيابة العامة أو خبير تندبه المحكمة. ويلتزم من يعين للإدارة وبالمحافظة على الأموال أو الأصول الأخرى وبحسن إدارتها، وردها مع غلتها المقبوضة طبقًا للأحكام المقررة في القانون المدني بشأن الوكالة في أعمال الإدارة والوديعة والحراسة، وذلك على النحو الذى يصدر بتنظيمه قرار من وزير العدل.
*تستبدل عبارة الأموال أو الأصول الأخرى بكلمة الأموال بموجب قانون رقم 14 لسنة 2020.$m226$,'0e3a9cdb6ae4042fc5c9eb499df8b18f',DATE '2020-03-04',NULL,'active',14,2020,$m226$استبدلت عبارة «الأموال أو الأصول الأخرى» بكلمة «الأموال» بالقانون رقم 14 لسنة 2020. تاريخ النفاذ مسجل تقريباً. النص قبل التعديل غير وارد فى المصدر.$m226$),
(8,1,1,$m226$للنائب العام اذا توافرت معلومات او دلائل جدية على وجود اموال ثابتة او منقولة متحصلة من انشطة أي إرهابي او كيان إرهابي مدرج او غير مدرج على قوائم الكيانات الارهابية او الارهابيين، او تستخدم في تمويله بأي صورة كانت أو في تمويل المنتسبين اليه او المرتبطين به، ان يأمر بالتحفظ على هذه الأموال أو الأصول الأخرى ومنع مالكيها أو حائزيها من التصرف فيها.
ويعرض أمر التحفظ والمنع من التصرف على الدائرة المنصوص عليها في المادة (3) من هذا القانون خلال شهر من تاريخ صدوره، للنظر في تأييده او إلغائه أو تعديله.
*تستبدل عبارة الأموال أو الأصول الأخرى بكلمة الأموال بموجب قانون رقم 14 لسنة 2020.
*مضافة بموجب قانون رقم 11 لسنة 2017.$m226$,'0c3974a66c46279ce1554e569b913b7c',DATE '2020-03-04',NULL,'active',14,2020,$m226$مادة مضافة بالقانون رقم 11 لسنة 2017 وعدل لفظها بالقانون رقم 14 لسنة 2020 (استبدال عبارة الأموال أو الأصول الأخرى). تاريخ النفاذ مسجل تقريباً (آخر تعديل).$m226$),
(9,0,1,$m226$في مجال مكافحة أنشطة الكيانات الإرهابية والإرهابيين، تتعاون الجهات القضائية والأجهزة المصرية المعنية بشئون الإرهاب - كل في حدود اختصاصه وبالتنسيق بينها - مع نظيراتها الأجنبية، من خلال تبادل المعلومات المساعدات والإنابات القضائية وتسليم الأشخاص والأشياء واسترداد الأموال أو الأصول الأخرى ونقل المحكوم عليهم، وإخطار الدول والمنظمات المعنية بالقرارات المشار إليها ففي هذا القانون، وغير ذلك من صور التعاون القضائي والمعلوماتي، وذلك كله وفقًا للقواعد التي تقررها الاتفاقيات الدولية النافذة في جمهورية مصر العربية، أو وفقًا لمبدأ المعاملة بالمثل.
فإذا تعلن الأمر بطلبات التعاون الدولي مع دولة أخرى في مجال تفعيل الإجراءات المحددة وفقاً لآليات تجميد الأموال أو الأصول الأخرى، يتعين توفير أكبر قدر ممكن من المعلومات الخاصة بتحديد هوية الأشخاص أو الكيانات المدرجة والمعلومات التي تؤيد طلب الإدراج.
*تستبدل عبارة الأموال أو الأصول الأخرى بكلمة الأموال بموجب قانون رقم 14 لسنة 2020.
*الفقرة الثانية مضافة بموجب قانون رقم 14 لسنة 2020.$m226$,'ab54a2d8eac34cb28b862450f9aa56a5',DATE '2020-03-04',NULL,'active',14,2020,$m226$عدلت بالقانون رقم 14 لسنة 2020 (استبدال عبارة الأموال أو الأصول الأخرى وإضافة الفقرة الثانية). تاريخ النفاذ مسجل تقريباً. النص قبل التعديل غير وارد فى المصدر.$m226$),
(10,0,1,$m226$يُنشر هذا القرار بقانون في الجريدة الرسمية، ويُعمل به اعتبارًا من اليوم التالي لتاريخ نشره
صدر برئاسة الجمهورية في 28 ربيع الآخر سنة 1436هـ (الموافق 17 فبراير سنة 2015م).$m226$,'6048ab85aa4ca619ac48bcac07f2b5bb',DATE '2015-02-17',NULL,'active',NULL,NULL,$m226$تاريخ بدء السريان الفعلى هو اليوم التالى لنشر القرار بقانون فى الجريدة الرسمية، وتاريخ النشر غير وارد فى المصدر، فسجل تاريخ الصدور 17/2/2015.$m226$);

DO $m226$
DECLARE
  v_law uuid;
  v_title text;
  v_new_law boolean := false;
  v_ins_art int;
  v_ins_ver int;
  v_cnt int;
  v_vcnt int;
BEGIN
  IF (SELECT count(*) FROM m226_art WHERE md5(body) <> body_md5) <> 0 OR (SELECT count(*) FROM m226_ver WHERE md5(body) <> body_md5) <> 0 THEN
    RAISE EXCEPTION '[226] تلف فى نص أحد الصفوف داخل الملف';
  END IF;
  IF (SELECT count(*) FROM m226_art) <> 12 OR (SELECT sum(char_length(body)) FROM m226_art) <> 10683 OR (SELECT count(*) FROM m226_ver) <> 15 THEN
    RAISE EXCEPTION '[226] عدد الصفوف أو النسخ أو طول النص داخل الملف غير مطابق';
  END IF;

  SELECT id, title INTO v_law, v_title FROM laws WHERE country_code='EG' AND law_no=8 AND law_year=2015 AND kind='law';
  IF v_law IS NOT NULL AND v_title NOT LIKE '%الكيانات الإرهابية%' THEN
    RAISE EXCEPTION '[226] يوجد مستند آخر برقم 8 لسنة 2015 (%): لا يُدمج هذا النص فيه', v_title;
  END IF;
  IF v_law IS NULL THEN
    INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at, last_amended_at, country_code, kind, governance_scope)
    VALUES (8, 2015, $t226$القانون رقم 8 لسنة 2015 فى شأن تنظيم قوائم الكيانات الإرهابية والإرهابيين (قرار رئيس الجمهورية بقانون، النسخة المحدثة من المطابع الأميرية بعد تعديلات القوانين 11 لسنة 2017 و2 لسنة 2020 و14 لسنة 2020)$t226$, $t226$قانون تنظيم قوائم الكيانات الإرهابية والإرهابيين 8/2015$t226$, 'aml_cft', 'amended', NULL, DATE '2015-02-17', DATE '2020-03-04', 'EG', 'law', false)
    RETURNING id INTO v_law;
    v_new_law := true;
  END IF;

  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, body)
  SELECT v_law, article_no, suffix, loc, body FROM m226_art
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING;
  GET DIAGNOSTICS v_ins_art = ROW_COUNT;

  INSERT INTO article_versions (article_id, version_no, body, effective_from, effective_to, status, amended_by_law_no, amended_by_law_year, change_note)
  SELECT a.id, m.version_no, m.body, m.eff, m.eff_to, m.status, m.am_no, m.am_yr, m.note
    FROM articles a JOIN m226_ver m ON m.article_no = a.article_no AND m.suffix = a.article_suffix_order
   WHERE a.law_id = v_law
     AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id = a.id)
  ON CONFLICT (article_id, version_no) DO NOTHING;
  GET DIAGNOSTICS v_ins_ver = ROW_COUNT;

  SELECT count(*) INTO v_cnt FROM articles a JOIN m226_art m ON m.article_no=a.article_no AND m.suffix=a.article_suffix_order
   WHERE a.law_id=v_law;
  IF v_cnt <> 12 THEN
    RAISE EXCEPTION '[226] عدد صفوف النص % بدل 12', v_cnt;
  END IF;
  SELECT count(*) INTO v_vcnt FROM article_versions v JOIN articles a ON a.id=v.article_id WHERE a.law_id=v_law;
  IF v_vcnt <> 15 THEN
    RAISE EXCEPTION '[226] عدد نسخ النص % بدل 15', v_vcnt;
  END IF;
  RAISE NOTICE '[226] قانون 8/2015: جديد=%، صفوف مضافة=%، نسخ مضافة=%', v_new_law, v_ins_art, v_ins_ver;
END
$m226$;
